<template><main class="sl-service"><header class="sl-header"><h1>International Top-up Settings</h1></header><p v-if="message" class="sl-alert" role="status">{{ message }}</p><form v-if="settings" class="sl-card" @submit.prevent="save"><label class="sl-toggle"><input type="checkbox" v-model="settings.enabled">Enable international airtime and data</label><label class="sl-field">Price multiplier<input class="sl-input" type="number" min="1" max="10" step="0.0001" v-model="settings.multiplier" required></label><p>VTUgate NGN price × multiplier = customer price. ₦6,000 × 1.03 = ₦6,180.</p><label class="sl-field">VTUgate API key / international code<input class="sl-input" type="password" v-model="apiKey" autocomplete="new-password" placeholder="Leave blank to keep the saved key"></label><p>{{ settings.api_key_configured?'API key configured':'API key required before enabling' }}. Saved encrypted on the server.</p><h2>Country calling codes</h2><p>Override a prefix using the country’s two-letter ISO code. Countries without overrides use VTUgate’s calling code.</p><div v-for="(c,index) in codes" :key="index" class="sl-row mb-2"><input class="sl-input" v-model="c.iso" placeholder="GH" aria-label="ISO country code" pattern="[A-Z]{2}" maxlength="2" required><input class="sl-input" v-model="c.code" placeholder="+233" aria-label="Calling code" pattern="\+[1-9][0-9]{0,3}" required><button class="sl-btn ghost" type="button" @click="codes.splice(index,1)">Remove</button></div><button class="sl-btn ghost" type="button" @click="codes.push({iso:'',code:''})">Add Country Code</button><button class="sl-btn sl-full mt-3" :disabled="busy">Save Settings</button></form><section class="sl-card"><h2>International Transactions</h2><button class="sl-btn ghost" @click="load">Refresh</button><div class="sl-table-wrap"><table class="sl-table"><thead><tr><th>Reference</th><th>Customer</th><th>Amount</th><th>Status</th><th>Provider ID</th><th>Action</th></tr></thead><tbody><tr v-for="p in transactions.data" :key="p.id"><td>{{ p.reference }}</td><td>{{ p.user_id }}</td><td>₦{{ (p.amount_kobo/100).toFixed(2) }}</td><td>{{ p.status }}</td><td>{{ p.transaction_id||'Awaiting confirmation' }}</td><td><button v-if="['pending','processing'].includes(p.status)" class="sl-btn ghost" @click="resolving=p;evidence='';outcome=''">Resolve</button></td></tr></tbody></table></div><div class="sl-row"><button class="sl-btn ghost" :disabled="transactions.current_page<=1" @click="load(transactions.current_page-1)">Previous</button><button class="sl-btn ghost" :disabled="transactions.current_page>=transactions.last_page" @click="load(transactions.current_page+1)">Next</button></div></section><div v-if="resolving" class="sl-modal-backdrop"><form class="sl-modal" @submit.prevent="resolve"><h2>Resolve {{ resolving.reference }}</h2><p>Confirm delivery or refund with VTUgate first. Record their support reference or evidence.</p><select v-model="outcome" class="sl-input" required><option disabled value="">Select confirmed outcome</option><option value="success">Delivered successfully</option><option value="reversed">Not delivered — refund wallet</option></select><textarea v-model="evidence" class="sl-input mt-3" minlength="15" maxlength="2000" required placeholder="Provider confirmation evidence"></textarea><button class="sl-btn sl-full mt-3" :disabled="busy">Record Outcome</button><button class="sl-btn ghost sl-full mt-2" type="button" @click="resolving=null">Cancel</button></form></div></main></template>
<script>
import axios from 'axios';import './service-ui.css';
export default{data(){return {settings:null,codes:[],apiKey:'',busy:false,message:'',transactions:{data:[]},resolving:null,evidence:'',outcome:''};},async mounted(){try{this.settings=(await axios.get('/api/admin/international/settings')).data.data;this.codes=Object.entries(this.settings.calling_codes).map(([iso,code])=>({iso,code}));}catch(e){this.message=this.error(e);}await this.load();},methods:{error(e){return e.response?.data?.message||'Request failed.';},async save(){this.busy=true;try{if(new Set(this.codes.map(c=>c.iso)).size!==this.codes.length)throw new Error('Duplicate country code');this.settings=(await axios.put('/api/admin/international/settings',{enabled:this.settings.enabled,multiplier:String(this.settings.multiplier),calling_codes:Object.fromEntries(this.codes.map(c=>[c.iso,c.code])),api_key:this.apiKey||null})).data.data;this.apiKey='';this.message='International settings saved.';}catch(e){this.message=e.message==='Duplicate country code'?e.message:this.error(e);}finally{this.busy=false;}},async load(page=1){try{this.transactions=(await axios.get('/api/admin/international/transactions',{params:{page:typeof page==='number'?page:1}})).data.data;}catch(e){this.message=this.error(e);}},async resolve(){this.busy=true;try{await axios.post(`/api/admin/international/transactions/${this.resolving.id}/resolve`,{outcome:this.outcome,evidence:this.evidence});this.resolving=null;await this.load();}catch(e){this.message=this.error(e);}finally{this.busy=false;}}}};
</script>
